'use strict';
/* Bitácora Gym 0.3: sin servidor; edita planes y guarda copias locales. */
const KEY='bitacora_gym_v3_main', SHADOW='bitacora_gym_v3_copy', VERSION=3;
const KG_PER_LB=0.45359237;
const $=id=>document.getElementById(id);
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
const round=(v,n=2)=>Math.round((Number(v)||0)*10**n)/10**n;
const fmt=n=>Number(n||0).toLocaleString('es-MX',{maximumFractionDigits:2});
const kg=(n,u)=>Number(n||0)*(u==='lb'?KG_PER_LB:1);
const unitFromKg=(n,u)=>Number(n||0)/(u==='lb'?KG_PER_LB:1);
const now=()=>new Date().toISOString();
const dateKey=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const dateLabel=d=>{if(!d)return 'Sin fecha';const a=String(d).split('-');return a.length===3?new Date(+a[0],+a[1]-1,+a[2]).toLocaleDateString('es-MX',{day:'numeric',month:'short',year:'numeric'}):String(d)};
const deep=o=>JSON.parse(JSON.stringify(o));
const id=prefix=>`${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,8)}`;
const normalize=t=>String(t||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const defaultSettings=()=>({autoBackup:true,reminders:true,hydration:'Recuerda hidratarte durante el día. Puedes personalizar este mensaje con la cantidad recomendada para ti por tu profesional de salud.'});
const catalogMap=new Map(BUILTIN_CATALOG.map(x=>[x.id,x]));
const LEGACY_NAMES=[
 ['Crunch en máquina','Sentadilla en máquina FreeMotion','Hip Thrust en máquina','Leg curl sentado en máquina','Extensión de rodilla en máquina','Elevación de talones en máquina de pie'],
 ['Rodillas al pecho colgado','Press de pecho plano','Aperturas en máquina (soporte en codo)','Curl Predicador en máquina','Curl Hércules en polea alta','Copa con mancuerna (a dos manos)','Extensión de codo unilateral en polea alta'],
 ['Press Pallof','Remo alto agarre supino en máquina (unilateral)','Face Pull en polea con cuerda','Remo unilateral con mancuerna','Prensa 45° (abierta)','Patada en Multi Hip','Aducción sentado en máquina']
];
const SAMPLE_CONFIG=[
 {title:'Tren inferior completo',short:'Piernas y glúteos',items:[
  [0,4,20,20,45,'Core'],[1,4,12,15,90,'Baja 3 s · sube 1 s'],[2,4,10,10,90,'Mantén 2 s'],[3,4,15,15,90,'Isquiotibiales'],[4,4,12,12,90,'Mantén 3 s'],[5,3,10,12,90,'Controlado']]},
 {title:'Tren superior',short:'Pecho y brazos',items:[
  [0,3,20,20,60,'Core'],[1,4,8,10,90,'Repeticiones controladas'],[2,3,15,15,90,'Mantén 2 s'],[3,4,8,10,90,'Pesado'],[4,4,12,15,90,'Por lado'],[5,4,8,10,90,'A dos manos'],[6,4,12,15,60,'Por lado']]},
 {title:'Full Body',short:'Espalda, hombros y piernas',items:[
  [0,3,15,15,45,'Por lado'],[1,4,10,10,90,'Por lado · mantén 1 s'],[2,4,10,12,60,'Mantén 3 s'],[3,4,10,10,90,'Por lado · pesado'],[4,4,10,12,90,'Controlado'],[5,4,12,12,60,'Por lado · mantén 1 s'],[6,3,10,12,60,'Pesado']]}
];
function findExercise(name){let norm=normalize(name);if(!norm)return null;for(const ex of [...BUILTIN_CATALOG,...S.customCatalog])if([ex.name,...(ex.aliases||[])].some(a=>normalize(a)===norm))return ex;return null}
function makeAssignment(name,sets,min,max,rest=90,note=''){let found=findExercise(name);return {id:id('item'),exerciseId:found?.id||null,freeName:found?null:String(name||'Ejercicio sin identificar').slice(0,100),sets:Number(sets)||null,minReps:Number(min)||null,maxReps:Number(max)||null,restSec:Number(rest)||60,note:String(note||'').slice(0,500)}}
function seedPlan(){const plan={id:id('plan'),title:'Mi rutina inicial · fuerza',status:'active',startDate:dateKey(),endDate:'',notes:'Rutina precargada a partir de tu programa anterior. Puedes editarla o duplicarla.',days:[],createdAt:now()};S.plans=[plan];S.activePlanId=plan.id;
 SAMPLE_CONFIG.forEach((d,index)=>plan.days.push({id:id('day'),title:d.title,short:d.short,items:d.items.map(arr=>makeAssignment(LEGACY_NAMES[index][arr[0]],arr[1],arr[2],arr[3],arr[4],arr[5]))}));return plan}
function initial(){return {version:VERSION,updatedAt:0,profile:{name:'',age:null,weight:null,height:null,goal:'fuerza'},profileCompleted:false,settings:defaultSettings(),plans:[],activePlanId:null,customCatalog:[],photos:{},active:null,history:[],last:{},unit:'kg'}}
let S=initial();let ui={screen:'home',planId:null,dayId:null,itemId:null,pick:null,catQuery:'',catMuscle:'',catEquipment:'',catalogView:null,pdfURL:null,pdfName:'',pdfText:'',pdfTarget:null,summary:null,photoTarget:null};
let storageState='checking', pendingSave=Promise.resolve(), dbPromise=null, toastTimer=null, weightDraft={weight:0,reps:10,unit:'kg'};
function allCatalog(){return [...BUILTIN_CATALOG,...S.customCatalog]}
function byExercise(id){return allCatalog().find(x=>x.id===id)||null}
function itemName(item){return byExercise(item.exerciseId)?.name||item.freeName||'Ejercicio pendiente'}
function mainPlan(){return S.plans.find(p=>p.id===S.activePlanId&&p.status==='active')||S.plans.find(p=>p.status==='active')||null}
function currentPlan(){return S.plans.find(p=>p.id===ui.planId)||mainPlan()}
function currentDay(){return currentPlan()?.days.find(d=>d.id===ui.dayId)||currentPlan()?.days[0]||null}
function currentItem(){return currentDay()?.items.find(x=>x.id===ui.itemId)||null}
function sessionExercise(){return S.active?.daySnapshot?.items[S.active.index]||null}
function setCount(s){return Object.values(s?.entries||{}).reduce((tot,arr)=>tot+(Array.isArray(arr)?arr.length:0),0)}
function repCount(s){return Object.values(s?.entries||{}).flat().reduce((t,x)=>t+(Number(x.reps)||0),0)}
function volume(s){return Object.values(s?.entries||{}).flat().reduce((t,x)=>t+(Number(x.reps)||0)*kg(x.weight,x.unit),0)}
function plannedSets(day){return(day?.items||[]).reduce((t,x)=>t+(Number(x.sets)||0),0)}
function sessionDayLast(planId,dayId){return S.history.find(x=>x.planId===planId&&x.dayId===dayId)}
function suggested(plan){if(!plan?.days.length)return null;const completed=S.history.find(s=>s.planId===plan.id&&plan.days.some(d=>d.id===s.dayId));if(!completed)return plan.days[0].id;let ix=plan.days.findIndex(d=>d.id===completed.dayId);return plan.days[(ix+1)%plan.days.length].id}
function activityName(t){return({none:'Sin registrar',treadmill:'Caminadora',elliptical:'Elíptica',bike:'Bicicleta',pool:'Alberca / natación',walk:'Caminata',other:'Otro'})[t?.type||'none']||'Otro'}
function validateStore(x){if(!x||x.version!==3||!Array.isArray(x.plans)||!Array.isArray(x.history)||!Array.isArray(x.customCatalog))throw Error('Respaldo incompatible o incompleto');return {...initial(),...x,profile:{...initial().profile,...x.profile},settings:{...defaultSettings(),...x.settings},photos:x.photos||{}}}
function openDB(){if(dbPromise)return dbPromise;dbPromise=new Promise(resolve=>{try{const req=indexedDB.open('BitacoraGym',3);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('state'))db.createObjectStore('state')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null);req.onblocked=()=>resolve(null)}catch(e){resolve(null)}});return dbPromise}
async function readDB(){let db=await openDB();if(!db)return null;return new Promise(resolve=>{try{let req=db.transaction('state','readonly').objectStore('state').get('main');req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>resolve(null)}catch(e){resolve(null)}})}
async function writeDB(data){let db=await openDB();if(!db)return false;return new Promise(resolve=>{try{let tx=db.transaction('state','readwrite');tx.objectStore('state').put(data,'main');tx.oncomplete=()=>resolve(true);tx.onerror=()=>resolve(false);tx.onabort=()=>resolve(false)}catch(e){resolve(false)}})}
function save(){S.updatedAt=Date.now();let copy=deep(S),ok=false;try{localStorage.setItem(KEY,JSON.stringify(copy));localStorage.setItem(SHADOW,JSON.stringify(copy));ok=true}catch(e){}storageState=ok?'local':'limited';pendingSave=pendingSave.catch(()=>{}).then(async()=>{if(await writeDB(copy))storageState='saved';return storageState});return pendingSave}
async function load(){let options=[];for(const key of [KEY,SHADOW]){try{const data=JSON.parse(localStorage.getItem(key)||'null');if(data?.version===3)options.push(data)}catch(e){}}
 const db=await readDB();if(db?.version===3)options.push(db);if(options.length){try{S=validateStore(options.sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0))[0]);storageState='saved'}catch(e){console.warn(e)}}
 if(!options.length){for(const key of ['bitacora_gym_v2_main','bitacora_gym_v2_shadow']){try{const older=JSON.parse(localStorage.getItem(key)||'null');if(older?.version===2){S=migrateBackupV2(older);await save();storageState='saved';break}}catch(e){}}}
 if(!S.plans.length){seedPlan();await save()}else if(!S.activePlanId){const p=S.plans.find(x=>x.status==='active');S.activePlanId=p?.id||null}
 ui.screen=S.profileCompleted?'home':'profile';render();if(location.protocol==='https:'&&'serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
}
function topbar(){return `<header class="top"><div class="identity"><div class="brand-symbol" aria-hidden="true">↗</div><div><div class="brand">Bitácora Gym</div><div class="subbrand">Planes editables · Versión 0.3 beta</div></div></div><button class="iconbtn" data-act="settings" aria-label="Configuración">⚙</button></header>`}
function banner(){if(location.protocol==='file:')return `<div class="notice red"><strong>Modo archivo local:</strong> no es seguro para registrar sesiones reales. Publica estos archivos bajo una dirección HTTPS fija y descarga respaldos periódicos.</div>`;
 if(storageState==='limited')return `<div class="notice red">No se pudo confirmar el almacenamiento local. Descarga un respaldo y revisa el espacio disponible en tu dispositivo.</div>`;return ''}
function tip(){if(!S.settings.reminders)return '';const tips=[S.settings.hydration,'Técnica primero: registra la carga con la que controlas el movimiento.','Descansar también es parte del entrenamiento.','Puedes cambiar de día cuando lo necesites, sin perder el historial.'];return tips[Math.floor(Date.now()/86400000)%tips.length]}
function nav(){const navs=[['home','⌂','Inicio'],['plans','▤','Planes'],['catalog','◈','Catálogo'],['history','▥','Historial']];const active=ui.screen==='home'||['warm','train','cardio','summary'].includes(ui.screen)?'home':ui.screen.startsWith('plan')||ui.screen==='pdf'?'plans':ui.screen.startsWith('cat')||ui.screen==='custom-exercise'?'catalog':ui.screen==='history'?'history':'';
 $('bottomNav').innerHTML=navs.map(([key,ico,label])=>`<button class="${active===key?'active':''}" data-act="nav" data-screen="${key}" aria-label="${label}"><span class="nav-icon">${ico}</span>${label}</button>`).join('')}
function render(){const views={home,plans,planEditor,assignmentEditor,catalog,customExercise,pdf,profile,warm,train,cardio,summary,history,settings};$('app').innerHTML=topbar()+(views[ui.screen]||home)();nav();document.title='Bitácora Gym · '+ui.screen;}
function go(screen){ui.screen=screen;render();scrollTo({top:0,behavior:'instant'})}
function toast(t){let el=$('toast');el.textContent=t;el.classList.remove('hide');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.add('hide'),2800)}
function download(contents,name,type){const b=new Blob([contents],{type}),href=URL.createObjectURL(b),a=document.createElement('a');a.href=href;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),12000)}
function backup(auto=false){download(JSON.stringify({app:'Bitacora Gym',version:3,exportedAt:now(),data:S},null,2),`bitacora-gym-respaldo-${dateKey()}.json`,'application/json');if(!auto)toast('Respaldo solicitado. Comprueba la carpeta Descargas.');}
function csvExport(){const csvCell=t=>'"'+String(t??'').replaceAll('"','""')+'"';const rows=[['Fecha','Plan','Día','Ejercicio','Serie','Repeticiones','Peso','Unidad','Equivalencia kg','Calentamiento','Min calentamiento','Cardio','Min cardio']];for(const s of S.history){let any=false;for(const ex of s.daySnapshot?.items||[])for(const [index,r] of (s.entries?.[ex.id]||[]).entries()){any=true;rows.push([s.date,s.planName,s.daySnapshot.title,ex.recordedName||itemName(ex),index+1,r.reps,r.weight,r.unit,round(kg(r.weight,r.unit),3),activityName(s.warmup),s.warmup?.minutes,activityName(s.cardio),s.cardio?.minutes])}if(!any)rows.push([s.date,s.planName,s.daySnapshot?.title,'Sin series','','','','','',activityName(s.warmup),s.warmup?.minutes,activityName(s.cardio),s.cardio?.minutes])}
 download('\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),`bitacora-gym-historial-${dateKey()}.csv`,'text/csv;charset=utf-8')}
function renderDateFields(p){return `<div class="two"><div class="field"><label for="planStart">Fecha de inicio (opcional)</label><input id="planStart" type="date" value="${escapeHTML(p.startDate||'')}"></div><div class="field"><label for="planEnd">Fecha de término (opcional)</label><input id="planEnd" type="date" value="${escapeHTML(p.endDate||'')}"></div></div>`}
function home(){const p=mainPlan(),next=suggested(p);return `<div class="title-block"><div class="kicker">Tu entrenamiento</div><h1>${S.profile.name?'¡Hola, '+escapeHTML(S.profile.name)+'!':'Entrena. Registra. Progresa.'}</h1><p>Tu siguiente día es una sugerencia; puedes repetir cualquiera sin perder tu historial.</p></div>${banner()}
 ${S.active?`<section class="card active"><div class="kicker">Sesión en curso</div><h2 style="margin:8px 0">${escapeHTML(S.active.planName)} · ${escapeHTML(S.active.daySnapshot?.title)}</h2><div class="muted small">${setCount(S.active)} series guardadas · ${dateLabel(S.active.date)}</div><button class="btn primary block" data-act="resume" style="margin-top:12px">▶ Continuar sesión</button></section>`:''}
 
 ${p?`<div class="section-head"><h2>${escapeHTML(p.title)}</h2><button data-act="editActive" class="btn sm">Editar</button></div>
 <div class="card-list">${p.days.map((d,i)=>{let last=sessionDayLast(p.id,d.id);return `<button class="card-click ${d.id===next?'recommended':''}" data-act="start" data-day="${escapeHTML(d.id)}"><div class="row spread"><strong>Día ${i+1} · ${escapeHTML(d.title)}</strong><span class="chip ${d.id===next?'good':''}">${d.id===next?'Sugerido':'Elegir →'}</span></div><div class="day-summary">${d.items.length} ejercicios · ${plannedSets(d)} series · ${last?'✓ Último: '+dateLabel(last.date):'Aún sin registrar'}</div></button>`}).join('')}</div>`:`<div class="empty">Todavía no hay un plan activo. Crea o activa un plan para comenzar.</div><button data-act="nav" data-screen="plans" class="btn primary block">Administrar planes</button>`}
 <div class="two" style="margin-top:18px"><button class="btn" data-act="nav" data-screen="plans">▤ Mis planes</button><button class="btn" data-act="nav" data-screen="history">▥ Historial</button></div><p class="footer">Los entrenamientos se guardan al registrar cada serie. Finaliza una sesión para pasarla al historial y descargar un respaldo completo.</p>`}
function profile(){const p=S.profile;return `<div class="title-block"><div class="kicker">${S.profileCompleted?'Actualizar':'Configuración inicial'}</div><h1>Tu perfil de entrenamiento</h1><p>Edad, estatura, peso y objetivo son opcionales. Estos datos no sustituyen la evaluación de tu entrenadora.</p></div><form id="profileForm"><div class="panel"><div class="field"><label for="pName">Apodo o nombre</label><input id="pName" maxlength="40" value="${escapeHTML(p.name||'')}" placeholder="Tu nombre"></div><div class="two"><div class="field"><label for="pAge">Edad</label><input id="pAge" type="number" min="13" max="110" value="${escapeHTML(p.age??'')}"></div><div class="field"><label for="pWeight">Peso (kg)</label><input id="pWeight" type="number" step="0.1" min="20" max="400" value="${escapeHTML(p.weight??'')}"></div></div><div class="two"><div class="field"><label for="pHeight">Estatura (cm)</label><input id="pHeight" type="number" step="0.1" min="100" max="250" value="${escapeHTML(p.height??'')}"></div><div class="field"><label for="pGoal">Objetivo</label><select id="pGoal"><option value="fuerza" ${p.goal==='fuerza'?'selected':''}>Fuerza</option><option value="recomposicion" ${p.goal==='recomposicion'?'selected':''}>Recomposición corporal</option><option value="resistencia" ${p.goal==='resistencia'?'selected':''}>Resistencia</option><option value="general" ${p.goal==='general'?'selected':''}>Condición general</option></select></div></div><button type="submit" class="btn primary block">Guardar perfil</button>${!S.profileCompleted?`<button type="button" class="btn ghost block" data-act="skipProfile">Omitir por ahora</button>`:''}</div></form>`}
function plans(){return `<div class="title-block"><div class="kicker">Tus programas</div><h1>Mis planes</h1><p>Crea, edita, duplica y archiva programas. El cambio de plan no borra entrenamientos anteriores.</p></div>${banner()}
 <div class="two"><button class="btn primary" data-act="newPlan">＋ Crear plan</button><button class="btn outline" data-act="openPDF">▤ Desde PDF / JSON</button></div>
 <div class="section-head"><h2>Planes guardados</h2><span class="chip">${S.plans.length} planes</span></div>
 ${S.plans.map(p=>`<div class="card ${p.status==='active'?'active':''}"><div class="row spread"><div class="grow"><h3>${escapeHTML(p.title)}</h3><p class="small muted" style="margin-top:5px">${p.days.length} días · ${p.days.reduce((t,d)=>t+d.items.length,0)} ejercicios · ${p.startDate?dateLabel(p.startDate):'Sin fecha de inicio'}</p></div><span class="chip ${p.status==='active'?'good':p.status==='draft'?'yellow':''}">${p.status==='active'?'Activo':p.status==='draft'?'Borrador':'Archivado'}</span></div><div class="row wrap" style="margin-top:12px"><button data-act="editPlan" data-id="${p.id}" class="btn sm">${p.status==='archived'?'Ver':'✎ Editar'}</button><button data-act="duplicatePlan" data-id="${p.id}" class="btn sm">Duplicar</button>${p.status==='draft'?`<button data-act="activatePlan" data-id="${p.id}" class="btn primary sm">Activar</button>`:''}${p.status==='active'?`<button data-act="archivePlan" data-id="${p.id}" class="btn sm">Archivar</button>`:''}${p.status==='draft'?`<button data-act="deletePlan" data-id="${p.id}" class="btn red sm">Eliminar</button>`:''}</div></div>`).join('')}
 <p class="footer">La rutina inicial es un plan independiente del catálogo: puedes sustituirla cuando recibas tu programa siguiente. No es necesario asignar una fecha final.</p>`}
function planEditor(){const p=currentPlan();if(!p)return '<div class="empty">Plan no disponible.</div>';const day=currentDay();const archived=p.status==='archived';return `<div class="title-block"><button class="btn ghost sm" data-act="nav" data-screen="plans">← Mis planes</button><div class="kicker" style="margin-top:10px">Editor · ${p.status==='active'?'Plan activo':p.status==='draft'?'Borrador':'Archivado'}</div><h1>${escapeHTML(p.title)}</h1><p>Modifica los días y los ejercicios. Los entrenamientos ya registrados no cambiarán.</p></div>
 <div class="panel"><div class="field"><label for="planTitle">Nombre del plan</label><input id="planTitle" maxlength="90" value="${escapeHTML(p.title)}" ${archived?'disabled':''}></div>${renderDateFields(p)}<div class="field"><label for="planNotes">Notas generales</label><textarea id="planNotes" maxlength="1000" ${archived?'disabled':''}>${escapeHTML(p.notes||'')}</textarea></div>${!archived?`<button data-act="savePlanInfo" class="btn block">Guardar información del plan</button>`:''}</div>
 <div class="section-head"><h2>Días de entrenamiento</h2>${!archived?`<button class="btn sm" data-act="newDay">＋ Día</button>`:''}</div>
 ${p.days.length?`<div class="tabrow">${p.days.map((d,i)=>`<button data-act="selectDay" data-id="${d.id}" class="${d.id===day?.id?'selected':''}">Día ${i+1}</button>`).join('')}</div>`:'<div class="empty">Agrega un día para comenzar.</div>'}
 ${day?`<div class="panel"><div class="field"><label for="dayTitle">Nombre del día</label><input id="dayTitle" maxlength="90" value="${escapeHTML(day.title)}" ${archived?'disabled':''}></div><div class="field"><label for="dayShort">Descripción</label><input id="dayShort" maxlength="120" value="${escapeHTML(day.short||'')}" ${archived?'disabled':''}></div>${!archived?`<div class="row wrap"><button data-act="saveDay" class="btn sm">Guardar día</button><button data-act="removeDay" class="btn red sm">Eliminar día</button></div>`:''}</div>
 <div class="section-head"><h2>Ejercicios (${day.items.length})</h2>${!archived?`<button data-act="pickExercise" class="btn sm primary">＋ Añadir</button>`:''}</div>
 ${day.items.map((it,i)=>`<div class="ex-editor"><div class="row spread"><div class="grow"><div class="ex-title">${i+1}. ${escapeHTML(itemName(it))}</div><div class="small muted" style="margin-top:5px">${it.sets??'—'} series · ${it.minReps??'—'}${it.maxReps&&it.maxReps!==it.minReps?'–'+it.maxReps:''} rep. · ${it.restSec||60} s de descanso</div>${!it.exerciseId?'<div class="flag">⚠ Pendiente de identificar en el catálogo</div>':''}</div>${!archived?`<div class="drag-actions"><button data-act="moveExercise" data-id="${it.id}" data-dir="-1" aria-label="Mover arriba" ${i===0?'disabled':''}>↑</button><button data-act="moveExercise" data-id="${it.id}" data-dir="1" aria-label="Mover abajo" ${i===day.items.length-1?'disabled':''}>↓</button></div>`:''}</div>${it.note?`<p class="small muted" style="margin:7px 0">${escapeHTML(it.note)}</p>`:''}${!archived?`<div class="row wrap" style="margin-top:8px"><button class="btn sm" data-act="editAssignment" data-id="${it.id}">Editar</button><button class="btn sm" data-act="replaceAssignment" data-id="${it.id}">${it.exerciseId?'Sustituir':'Vincular'}</button><button class="btn red sm" data-act="removeAssignment" data-id="${it.id}">Quitar</button></div>`:''}</div>`).join('')||'<div class="empty">Todavía no hay ejercicios para este día.</div>'}
 ${!archived?`<button data-act="pickExercise" class="btn outline block">＋ Agregar desde el catálogo</button>`:''}`:''}
 <div class="panel"><div class="row wrap">${p.status==='draft'?`<button class="btn primary" data-act="activatePlan" data-id="${p.id}">Activar este plan</button>`:''}<button class="btn" data-act="duplicatePlan" data-id="${p.id}">Duplicar plan</button><button class="btn outline" data-act="exportPlan" data-id="${p.id}">Exportar plan JSON</button></div>${p.status==='active'?'<p class="footer">Un plan activo puede editarse. Cada sesión crea una copia de sus ejercicios al iniciar, para proteger los registros anteriores.</p>':''}</div>`}
function assignmentEditor(){const item=currentItem();if(!item)return '<div class="empty">Ejercicio no disponible.</div>';let e=byExercise(item.exerciseId);return `<div class="title-block"><button class="btn ghost sm" data-act="backPlan">← Volver al plan</button><div class="kicker" style="margin-top:13px">Editar ejercicio del día</div><h1>${escapeHTML(itemName(item))}</h1><p>Los cambios se aplicarán a las próximas sesiones de este plan.</p></div>
 ${e?`<div class="chips"><span class="chip">${escapeHTML(e.muscle)}</span><span class="chip">${escapeHTML(e.equipment)}</span></div>`:'<div class="notice">Este ejercicio aún no está vinculado al catálogo. Puedes elegir uno equivalente o crear uno personalizado.</div>'}
 <div class="panel"><div class="two"><div class="field"><label for="aSets">Series</label><input id="aSets" type="number" inputmode="numeric" min="1" max="20" value="${item.sets??''}"></div><div class="field"><label for="aRest">Descanso (segundos)</label><input id="aRest" type="number" min="0" max="900" value="${item.restSec??60}"></div></div><div class="two"><div class="field"><label for="aMin">Repeticiones mín.</label><input id="aMin" type="number" min="1" max="1000" value="${item.minReps??''}"></div><div class="field"><label for="aMax">Repeticiones máx.</label><input id="aMax" type="number" min="1" max="1000" value="${item.maxReps??''}"></div></div><div class="field"><label for="aNote">Instrucciones de tu entrenadora</label><textarea id="aNote" maxlength="500">${escapeHTML(item.note||'')}</textarea></div><button data-act="saveAssignment" class="btn primary block">Guardar ejercicio</button><button data-act="replaceAssignment" data-id="${item.id}" class="btn outline block" style="margin-top:9px">Sustituir o vincular con catálogo</button></div>`}
const muscleOptions=['','Piernas','Glúteos','Pantorrillas','Pecho','Espalda','Hombros','Bíceps','Tríceps','Core','Cardio','Movilidad'];
const equipmentOptions=['','Máquina','Mancuerna','Barra','Polea','Peso corporal','Colchoneta','Banco','Smith','Caminadora','Elíptica','Bicicleta','Alberca','Sin equipo'];
function selectOptions(vals,selected){return vals.map((v,i)=>`<option value="${escapeHTML(v)}" ${v===selected?'selected':''}>${i===0?'Todos':escapeHTML(v)}</option>`).join('')}
function catalogItemMarkup(ex){const selecting=!!ui.pick;return `<div class="ex-item"><div class="ex-icon" aria-hidden="true">${iconFor(ex.family)}</div><div class="grow"><div class="name">${escapeHTML(ex.name)}</div><div class="desc">${escapeHTML(ex.muscle)} · ${escapeHTML(ex.equipment)}${ex.custom?' · Personalizado':''}</div></div><button class="btn sm ${selecting?'primary':''}" data-act="${selecting?'chooseExercise':'detailExercise'}" data-id="${ex.id}">${selecting?'Añadir':'Ver'}</button></div>`}
function iconFor(f){return ({squat:'◧',pressleg:'◧',legext:'◧',legcurl:'◧',hinge:'↘',lunge:'⇄',glute:'◩',hip:'◉',calf:'↑',chest:'⊣',pull:'⇩',row:'⇠',shoulder:'↑',curl:'◡',tri:'↦',core:'◈',cardio:'♥',stretch:'↔'})[f]||'◆'}
function catalogResults(){const q=normalize(ui.catQuery),filtered=allCatalog().filter(ex=>(!ui.catMuscle||ex.muscle===ui.catMuscle)&&(!ui.catEquipment||ex.equipment===ui.catEquipment)&&(!q||normalize([ex.name,...(ex.aliases||[])].join(' ')).includes(q)));return `<p class="small muted" style="margin:9px 0">${filtered.length} ejercicios encontrados de ${allCatalog().length}</p>${filtered.slice(0,110).map(catalogItemMarkup).join('')||'<div class="empty">No hay coincidencias. Puedes crear un ejercicio personalizado.</div>'}`}
function exerciseSketch(ex){if(!ex)return '';const family=ex.family||'core', arrow=(['squat','lunge','glute','legext','legcurl','calf','shoulder','stretch'].includes(family)?'↕':['chest','tri'].includes(family)?'↔':['row','pull','curl'].includes(family)?'⇄':'↕');return `<figure class="sketch"><svg role="img" aria-label="Esquema orientativo de postura y dirección de movimiento" viewBox="0 0 330 160" xmlns="http://www.w3.org/2000/svg"><rect x="24" y="131" width="282" height="3" rx="2" fill="#486b79"/><path d="M73 130 V56 H112 M92 56 V126" stroke="#5f93a9" stroke-width="8" fill="none" stroke-linecap="round"/><circle cx="182" cy="34" r="15" fill="#a9dfce"/><path d="M181 49 L177 91 M177 64 L145 88 M178 64 L208 82 M177 91 L157 129 M177 91 L204 128" stroke="#a9dfce" stroke-width="9" fill="none" stroke-linecap="round"/><path d="M216 43 L257 43 L257 103" stroke="#618aa1" stroke-width="9" fill="none" stroke-linecap="round"/><circle cx="257" cy="101" r="12" fill="#d6c48d"/><text x="280" y="85" fill="#a7f0d2" font-size="24" font-weight="700" text-anchor="middle">${arrow}</text></svg><figcaption>Esquema genérico, no una demostración técnica. Consulta las indicaciones de tu entrenadora.</figcaption></figure>`}
function catalogDetailMarkup(ex){if(!ex)return '';let photo=S.photos[ex.id];return `<div class="panel"><button class="btn ghost sm" data-act="catalogBack">← Volver al catálogo</button><h2 style="margin:12px 0">${escapeHTML(ex.name)}</h2><div class="chips"><span class="chip">${escapeHTML(ex.muscle)}</span><span class="chip">${escapeHTML(ex.equipment)}</span></div>${photo?`<img class="photo" src="${photo}" alt="Foto guardada para este ejercicio" style="margin-top:12px">`:exerciseSketch(ex)}<h3 style="margin-top:9px">Referencia de ejecución</h3><ol class="note-list">${(ex.instructions||[]).map(t=>`<li>${escapeHTML(t)}</li>`).join('')}</ol><div class="row wrap"><button class="btn sm" data-act="photo" data-id="${ex.id}">📷 Guardar foto de mi máquina</button>${photo?`<button class="btn red sm" data-act="removePhoto" data-id="${ex.id}">Quitar foto</button>`:''}<button class="btn sm" data-act="videoSearch" data-id="${ex.id}">Buscar demostración ↗</button></div>${ui.pick?`<button class="btn primary block" style="margin-top:12px" data-act="chooseExercise" data-id="${ex.id}">Agregar al plan</button>`:''}</div>`}
function catalog(){let select=ui.pick;return `<div class="title-block"><div class="kicker">${select?'Seleccionar ejercicio':'Biblioteca de ejercicios'}</div><h1>${select?'Elige un ejercicio':'Catálogo de ejercicios'}</h1><p>${select?'Selecciona uno para añadirlo o sustituirlo en el plan.':'Ejercicios por músculo y equipo, con nombres alternativos, indicaciones básicas y fotos personalizadas.'}</p></div>${select?`<button class="btn ghost sm" data-act="cancelPick">← Regresar al editor</button>`:''}
 ${ui.catalogView?catalogDetailMarkup(byExercise(ui.catalogView)):`<div class="searchbar"><input type="search" id="catSearch" autocomplete="off" placeholder="Buscar: remo, curl, prensa…" value="${escapeHTML(ui.catQuery)}" aria-label="Buscar ejercicios"><button class="btn sm" data-act="clearSearch">Limpiar</button></div><div class="filters"><select id="catMuscle" aria-label="Grupo muscular">${selectOptions(muscleOptions,ui.catMuscle)}</select><select id="catEquipment" aria-label="Equipo">${selectOptions(equipmentOptions,ui.catEquipment)}</select></div><button class="btn outline block" data-act="newCustomExercise">＋ Crear ejercicio personalizado</button><div id="catResults">${catalogResults()}</div>`}`}
function customExercise(){return `<div class="title-block"><button class="btn ghost sm" data-act="catalogBack">← Volver</button><div class="kicker" style="margin-top:12px">Mi catálogo</div><h1>Crear ejercicio personalizado</h1><p>Para máquinas específicas del gimnasio o nombres diferentes a los del catálogo.</p></div><form id="customForm" class="panel"><div class="field"><label for="exName">Nombre del ejercicio</label><input id="exName" maxlength="100" required placeholder="Nombre como aparece en tu plan"></div><div class="two"><div class="field"><label for="exMuscle">Grupo muscular</label><select id="exMuscle">${muscleOptions.slice(1).map(v=>`<option value="${escapeHTML(v)}">${escapeHTML(v)}</option>`).join('')}</select></div><div class="field"><label for="exEquipment">Equipo</label><select id="exEquipment">${equipmentOptions.slice(1).map(v=>`<option value="${escapeHTML(v)}">${escapeHTML(v)}</option>`).join('')}</select></div></div><div class="field"><label for="exAliases">Otros nombres (separados por coma)</label><input id="exAliases" maxlength="300" placeholder="Nombre alternativo"></div><div class="field"><label for="exInstructions">Indicaciones (una por línea)</label><textarea id="exInstructions" maxlength="1500" placeholder="Cómo se realiza según tu entrenadora"></textarea></div><button class="btn primary block" type="submit">Guardar en catálogo</button></form>`}
function pdf(){return `<div class="title-block"><button class="btn ghost sm" data-act="nav" data-screen="plans">← Mis planes</button><div class="kicker" style="margin-top:12px">Nuevo programa</div><h1>Crear a partir de un PDF</h1><p>Consulta tu PDF mientras armas el plan. Si puedes copiar su texto, la app también puede interpretar líneas simples y crear un borrador para revisar.</p></div>
 <div class="panel"><h3>1. Consultar el documento</h3><button class="btn block" data-act="loadPDF" style="margin-top:12px">▤ Seleccionar PDF del entrenador</button>${ui.pdfName?`<div class="display-file">📄 ${escapeHTML(ui.pdfName)} <button class="btn sm" data-act="viewPDF">Abrir ↗</button></div><iframe class="pdf-embed" title="Vista previa del PDF seleccionado" src="${ui.pdfURL}"></iframe><p class="micro">Algunos celulares no muestran PDFs dentro de la app; toca «Abrir» para verlo en otra pestaña. El archivo no se sube ni se guarda.</p>`:''}</div>
 <div class="panel"><h3>2. Crear borrador desde texto</h3><p class="small muted" style="margin:8px 0">Pega el texto seleccionado del PDF, con una línea por ejercicio. Formatos admitidos: <strong>Sentadilla 4x12-15 90s</strong> o <strong>Remo 3 x 10</strong>; identifica encabezados como «Día 1: Piernas».</p><div class="field"><label for="importTitle">Nombre del programa</label><input id="importTitle" maxlength="90" value="${escapeHTML(ui.importTitle||'Nuevo programa')}" placeholder="Plan de diciembre"></div><div class="field"><label for="pdfText">Contenido del plan</label><textarea id="pdfText" rows="9" style="min-height:180px" placeholder="Día 1: Piernas\nSentadilla en máquina FreeMotion 4x12-15 90s\nHip Thrust en máquina 4x10 90s\n\nDía 2: Tren superior\nPress de pecho plano 4x8-10 90s">${escapeHTML(ui.pdfText||'')}</textarea></div><button class="btn primary block" data-act="parseText">Analizar texto y crear borrador</button></div>
 <div class="panel"><h3>3. Otras opciones</h3><p class="small muted" style="margin:9px 0">También puedes crear manualmente desde el catálogo o importar un plan en JSON preparado a partir del PDF en ChatGPT. Esto es útil con documentos escaneados.</p><div class="col"><button class="btn" data-act="importPlan">Importar un plan JSON</button><button class="btn" data-act="templatePlan">Descargar ejemplo JSON</button><button class="btn outline" data-act="newPlan">Crear manualmente</button></div></div><p class="footer">Esta versión no hace OCR ni extrae automáticamente texto del interior del archivo PDF. Al importar texto o JSON, comprueba siempre las coincidencias y cantidades antes de activar el plan.</p>`}
function parsePlanText(text,title){let lines=String(text||'').split(/\r?\n/),days=[],day=null,found=0,skipped=0;for(let raw of lines){let line=raw.trim().replace(/^[•*\-]\s*/,'');if(!line)continue;const header=line.match(/^(?:d[ií]a|day)\s*(\d{1,2})\s*[:.\-)–—]?\s*(.*)$/i);
 if(header){day={id:id('day'),title:header[2]?.trim()||'Día '+header[1],short:'',items:[]};days.push(day);continue}
 // nombre seguido de 3x12 o 4 series de 10, descanso opcional
 const parsed=line.match(/^(.*?)\s+(\d{1,2})\s*(?:[x×]|series?\s*(?:de\s*)?)\s*(\d{1,3})(?:\s*[-–a]\s*(\d{1,3}))?(?:.*?(\d{2,3})\s*(?:seg(?:undos?)?|s)\b)?/i);
 if(!parsed){skipped++;continue}
 const name=parsed[1].replace(/[:\-–,\s]+$/,'').trim();if(!name||name.length>120){skipped++;continue}
 if(!day){day={id:id('day'),title:'Día 1',short:'',items:[]};days.push(day)}
 const rest=parsed[5]?Number(parsed[5]):90;day.items.push(makeAssignment(name,+parsed[2],+parsed[3],+(parsed[4]||parsed[3]),rest,''));found++;
 }if(!found)throw Error('No pude identificar ejercicios en el texto. Prueba con líneas como «Sentadilla 4x12-15 90s» o crea el plan manualmente.');return {days,found,skipped}}
function normalizePlanImport(raw){const plan=raw?.plan||raw;if(!plan||typeof plan!=='object'||!Array.isArray(plan.days)||!plan.days.length||plan.days.length>20)throw Error('El JSON necesita un objeto plan con una lista days.');const out={id:id('plan'),title:String(plan.title||'Plan importado').slice(0,90),status:'draft',startDate:String(plan.startDate||''),endDate:String(plan.endDate||''),notes:String(plan.notes||'Importado desde JSON; revisa los ejercicios.').slice(0,1000),createdAt:now(),days:[]};
 for(const d of plan.days){if(!Array.isArray(d.exercises||d.items))throw Error('Un día no tiene lista exercises.');let items=[];for(const x of (d.exercises||d.items)){const name=String(x.name||x.freeName||x.exercise||'').trim();if(!name)throw Error('Falta el nombre de un ejercicio.');const reps=String(x.reps||'');let m=reps.match(/(\d+)\s*[-–]\s*(\d+)/);const min=Number(x.minReps||x.min||m?.[1]||Number(reps)||0);const max=Number(x.maxReps||x.max||m?.[2]||min);items.push(makeAssignment(name,Number(x.sets),min,max,Number(x.restSec||x.rest||90),x.note||''));}out.days.push({id:id('day'),title:String(d.title||`Día ${out.days.length+1}`).slice(0,90),short:String(d.short||'').slice(0,120),items})}return out}
function planExport(p){return {format:'bitacora-gym-plan-1',plan:{title:p.title,startDate:p.startDate,endDate:p.endDate,notes:p.notes,days:p.days.map(d=>({title:d.title,short:d.short,exercises:d.items.map(x=>({name:itemName(x),sets:x.sets,reps:x.minReps===x.maxReps?String(x.minReps||''):`${x.minReps||''}-${x.maxReps||''}`,restSec:x.restSec,note:x.note}))}))}}}
function samplePlanJSON(){return {format:'bitacora-gym-plan-1',plan:{title:'Ejemplo de nuevo programa',startDate:'',endDate:'',notes:'Revisar con la entrenadora',days:[{title:'Piernas',short:'Día 1',exercises:[{name:'Sentadilla en máquina FreeMotion',sets:4,reps:'12-15',restSec:90,note:'Movimiento controlado'},{name:'Prensa 45°',sets:4,reps:'10-12',restSec:90,note:''}]},{title:'Pecho y brazos',short:'Día 2',exercises:[{name:'Press de pecho plano',sets:4,reps:'8-10',restSec:90,note:''}]}]}}}
function warm(){const s=S.active;if(!s)return '<div class="empty">No hay una sesión en curso.</div>';return `<div class="title-block"><div class="kicker">Inicio de sesión</div><h1>Calentamiento</h1><p>${escapeHTML(s.daySnapshot.title)} · Registra lo que ya hiciste antes de iniciar la fuerza.</p></div><div class="panel"><div class="field"><label for="warmType">Actividad</label><select id="warmType"><option value="none">No registrar</option>${['elliptical','treadmill','bike','walk','other'].map(t=>`<option value="${t}" ${s.warmup?.type===t?'selected':''}>${activityName({type:t})}</option>`).join('')}</select></div><div class="field"><label for="warmMinutes">Minutos</label><input id="warmMinutes" type="number" inputmode="numeric" min="0" max="300" value="${s.warmup?.minutes||''}" placeholder="Ej. 10"></div><div class="two"><button class="btn primary" data-act="saveWarm">Continuar →</button><button class="btn" data-act="skipWarm">Omitir</button></div></div>`}
function initDraft(){const s=S.active,ex=sessionExercise();if(!s||!ex)return;const arr=s.entries[ex.id]||[],prior=arr.at(-1)||S.last[ex.exerciseId||ex.freeName];weightDraft={reps:prior?.reps||ex.minReps||10,weight:prior?.weight||0,unit:prior?.unit||S.unit||'kg'}}
function exCounter(label,val,act){return `<div><div class="micro" style="margin-bottom:8px;font-weight:800">${label}</div><div class="counter"><button data-act="${act}Minus" aria-label="Disminuir ${label}">−</button><input inputmode="decimal" type="number" id="${act}" value="${escapeHTML(val)}" min="0"><button data-act="${act}Plus" aria-label="Aumentar ${label}">＋</button></div></div>`}
function train(){const s=S.active;if(!s)return '<div class="empty">No hay sesión en curso.</div>';const ex=sessionExercise();if(!ex)return '<div class="empty">Este día no tiene ejercicios.</div>';const cat=byExercise(ex.exerciseId),name=ex.recordedName||itemName(ex),arr=s.entries[ex.id]||[];const total=plannedSets(s.daySnapshot),logged=setCount(s),pct=total?Math.min(100,logged/total*100):0;return `<div class="title-block"><div class="kicker">${escapeHTML(s.planName)} · ${escapeHTML(s.daySnapshot.title)}</div><h1>Registra tu ejercicio</h1><p>${logged} de ${total} series previstas · Desliza hacia los lados para cambiar de ejercicio.</p></div><div class="progress"><div style="width:${pct}%"></div></div>
 <div id="swipeZone" class="exercise-detail swipe"><div class="row spread"><button class="btn sm" data-act="prevExercise" ${s.index===0?'disabled':''}>← Anterior</button><span class="chip">${s.index+1} / ${s.daySnapshot.items.length}</span><button class="btn sm" data-act="nextExercise" ${s.index===s.daySnapshot.items.length-1?'disabled':''}>Siguiente →</button></div><h2 style="margin:14px 0 8px">${escapeHTML(name)}</h2><div class="chips"><span class="chip">${ex.sets||'—'} series</span><span class="chip">${ex.minReps||'—'}–${ex.maxReps||'—'} rep.</span><span class="chip">${ex.restSec||0} s descanso</span></div>
 ${cat?S.photos[cat.id]?`<img class="photo" style="margin-top:12px" src="${S.photos[cat.id]}" alt="Foto de la máquina">`:exerciseSketch(cat):'<div class="notice">Ejercicio no vinculado. Revisa el nombre y las indicaciones de tu entrenadora.</div>'}
 ${cat?`<div class="row wrap" style="margin:10px 0"><button class="btn sm" data-act="photo" data-id="${cat.id}">📷 Foto de la máquina</button><button class="btn sm" data-act="videoSearch" data-id="${cat.id}">Ver demostración ↗</button></div><details><summary class="small" style="cursor:pointer">Ver indicaciones generales</summary><ul class="note-list">${(cat.instructions||[]).map(t=>`<li>${escapeHTML(t)}</li>`).join('')}</ul></details>`:''}${ex.note?`<div class="notice green">📝 ${escapeHTML(ex.note)}</div>`:''}
 <div class="two" style="margin-top:18px">${exCounter('REPETICIONES',weightDraft.reps,'reps')}${exCounter('PESO / CARGA',weightDraft.weight,'weight')}</div>
 <div class="unit-switch"><button data-act="changeUnit" data-unit="kg" class="${weightDraft.unit==='kg'?'selected':''}">kg</button><button data-act="changeUnit" data-unit="lb" class="${weightDraft.unit==='lb'?'selected':''}">lb</button></div><div id="conversion" class="convert-box">${conversionText()}</div><div class="dots">${Array.from({length:Math.max(arr.length,ex.sets||0)},(_,i)=>`<span class="dot ${i<arr.length?'done':''}">${i<arr.length?'✓':i+1}</span>`).join('')}</div><div class="small muted">${arr.map((r,i)=>`${i+1}. ${r.reps} rep × ${fmt(r.weight)} ${r.unit}`).join(' · ')||'Sin series registradas todavía.'}</div>
 <div class="floating"><button class="btn primary block" data-act="logSet">✓ Registrar serie ${arr.length+1}</button></div><div class="row wrap"><button class="btn sm" data-act="undoSet" ${!arr.length?'disabled':''}>↶ Deshacer última</button><button class="btn sm" data-act="showExerciseList">Ver lista de ejercicios</button></div></div>
 <details id="allExercises" class="panel"><summary>Seleccionar ejercicio directamente</summary><div class="col" style="margin-top:12px">${s.daySnapshot.items.map((x,i)=>`<button data-act="jumpExercise" data-index="${i}" class="btn ${i===s.index?'outline':''} sm" style="justify-content:flex-start">${i+1}. ${escapeHTML(x.recordedName||itemName(x))} · ${(s.entries[x.id]||[]).length}/${x.sets}</button>`).join('')}</div></details>
 <div class="two" style="margin-top:18px"><button class="btn" data-act="backWarm">↶ Calentamiento</button><button class="btn primary" data-act="openCardio">Terminar fuerza →</button></div><button class="btn red block" style="margin-top:10px" data-act="discardSession">Descartar esta sesión</button>`}
function conversionText(){const n=weightDraft.weight,u=weightDraft.unit;return u==='kg'?`${fmt(n)} kg = ${fmt(round(unitFromKg(n,'lb'),2))} lb`:`${fmt(n)} lb = ${fmt(round(kg(n,'lb'),2))} kg`}
function cardio(){const s=S.active;if(!s)return '<div class="empty">No hay sesión en curso.</div>';const last=S.history[0]?.cardio?.type||'none';return `<div class="title-block"><div class="kicker">Último paso</div><h1>Cardio principal</h1><p>Registra una actividad. Puedes alternar natación y caminadora sin duplicar cardio.</p></div><div class="panel"><div class="field"><label for="cardioType">Actividad</label><select id="cardioType"><option value="none">Hoy no hice cardio</option>${['pool','treadmill','elliptical','bike','walk','other'].map(t=>`<option value="${t}" ${s.cardio?.type===t?'selected':''}>${activityName({type:t})}</option>`).join('')}</select></div><div class="field"><label for="cardioMinutes">Duración (minutos)</label><input id="cardioMinutes" type="number" inputmode="numeric" min="0" max="300" value="${s.cardio?.minutes||''}" placeholder="Ej. 40"></div>${last!=='none'?`<div class="notice green">Tu cardio principal anterior fue: ${activityName({type:last})}. Puedes alternarlo si corresponde a tu programa.</div>`:''}<button class="btn primary block" data-act="finishSession">✓ Finalizar y ver resumen</button><button class="btn ghost block" data-act="backTrain">← Volver a fuerza</button></div>`}
function summary(){const s=ui.summary||S.history[0];if(!s)return '<div class="empty">No hay resumen disponible.</div>';return `<div class="title-block"><div class="kicker">Sesión finalizada ✓</div><h1>¡Bien hecho!</h1><p>${escapeHTML(s.planName)} · ${escapeHTML(s.daySnapshot.title)} · ${dateLabel(s.date)}</p></div><div class="stats"><div class="stat"><strong>${setCount(s)}</strong><span>Series</span></div><div class="stat"><strong>${repCount(s)}</strong><span>Repeticiones</span></div><div class="stat"><strong>${fmt(round(volume(s),1))}</strong><span>kg·rep (volumen)</span></div></div><div class="panel"><h3>Actividades del día</h3><p style="margin-top:11px">Calentamiento: <b>${activityName(s.warmup)}</b> · ${s.warmup?.minutes||0} min</p><p>Cardio principal: <b>${activityName(s.cardio)}</b> · ${s.cardio?.minutes||0} min</p><hr class="line"><h3>Ejercicios</h3>${s.daySnapshot.items.map(x=>{const arr=s.entries?.[x.id]||[];return `<div class="history-row"><b>${escapeHTML(x.recordedName||itemName(x))}</b><div class="small muted">${arr.length} series${arr.length?' · '+arr.map(z=>`${z.reps} rep × ${fmt(z.weight)} ${z.unit}`).join(' · '):''}</div></div>`}).join('')}</div><button class="btn primary block" data-act="backup">⬇ Descargar respaldo completo</button><button class="btn block" style="margin-top:10px" data-act="nav" data-screen="home">Volver al inicio</button><p class="footer">Si tienes activado el respaldo automático, verifica que el navegador haya descargado el archivo JSON. El mensaje de confirmación en pantalla no acredita una copia fuera del dispositivo.</p>`}
function history(){return `<div class="title-block"><div class="kicker">Tu progreso</div><h1>Historial</h1><p>${S.history.length} sesiones finalizadas. Cada una conserva el plan y ejercicios utilizados en esa fecha.</p></div><div class="panel">${S.history.map(s=>`<div class="history-row"><details><summary>${dateLabel(s.date)} · ${escapeHTML(s.daySnapshot?.title||'Sesión')}</summary><div class="small muted" style="margin-top:9px">${escapeHTML(s.planName||'Plan')} · ${setCount(s)} series · ${repCount(s)} rep · ${fmt(round(volume(s),1))} kg·rep</div><p class="small">Calentamiento: ${activityName(s.warmup)} ${s.warmup?.minutes||0} min · Cardio: ${activityName(s.cardio)} ${s.cardio?.minutes||0} min</p>${(s.daySnapshot?.items||[]).map(x=>`<p class="small" style="margin:8px 0"><b>${escapeHTML(x.recordedName||itemName(x))}</b><br>${(s.entries?.[x.id]||[]).map(r=>`${r.reps} rep × ${fmt(r.weight)} ${r.unit}`).join(' · ')||'Sin series'}</p>`).join('')}</details></div>`).join('')||'<div class="empty">Todavía no hay sesiones finalizadas.</div>'}</div><div class="two"><button class="btn" data-act="csv">⬇ CSV</button><button class="btn primary" data-act="backup">⬇ Respaldo</button></div>`}
function settings(){const p=S.profile;return `<div class="title-block"><div class="kicker">Seguridad y preferencias</div><h1>Tus datos</h1><p>La información se guarda localmente en el navegador. El respaldo es indispensable para recuperar tus registros si cambias de dispositivo o se borra el almacenamiento.</p></div>${banner()}
 <div class="panel"><h3>Respaldo</h3><p class="small muted" style="margin:9px 0">Estado local: <strong>${storageState==='saved'?'IndexedDB y copia adicional guardada':storageState==='local'?'Copia del navegador guardada':'Guardado por verificar'}</strong>. No equivale a una copia en la nube.</p><div class="col"><button class="btn primary block" data-act="backup">⬇ Descargar respaldo JSON</button><button class="btn block" data-act="restore">↥ Restaurar respaldo JSON</button><button class="btn block" data-act="csv">⬇ Exportar historial CSV</button></div><div class="row" style="margin-top:13px"><input type="checkbox" id="autoBackup" ${S.settings.autoBackup?'checked':''}><label for="autoBackup" class="small">Solicitar respaldo al finalizar cada sesión</label></div><p class="footer">El navegador puede bloquear descargas automáticas. Comprueba Descargas después de entrenar.</p></div>
 <div class="panel"><h3>Recordatorios amables</h3><div class="row" style="margin-top:13px"><input type="checkbox" id="reminders" ${S.settings.reminders?'checked':''}><label for="reminders" class="small">Incluir recordatorios de hidratación en los mensajes de KIRO</label></div><div class="field"><label for="hydration">Consejo de hidratación para KIRO</label><textarea id="hydration" maxlength="400">${escapeHTML(S.settings.hydration)}</textarea></div><button class="btn block" data-act="saveSettings">Guardar preferencias</button></div>
 <div class="panel"><h3>Tu perfil</h3><p class="small muted" style="margin:9px 0">${p.age?escapeHTML(p.age)+' años':'Edad opcional'} · ${p.weight?fmt(p.weight)+' kg':'Peso opcional'} · ${p.height?fmt(p.height)+' cm':'Estatura opcional'}</p><button class="btn block" data-act="nav" data-screen="profile">Editar perfil</button></div>
 <div class="notice">Para uso continuo recomendamos instalar el sitio HTTPS en la pantalla de inicio. Abrir distintos archivos HTML puede crear almacenes diferentes. Esta versión no sincroniza datos entre dispositivos.</div>`}
function createPlan(){const p={id:id('plan'),title:'Nuevo plan de entrenamiento',status:'draft',startDate:'',endDate:'',notes:'',createdAt:now(),days:[{id:id('day'),title:'Día 1',short:'',items:[]}]};S.plans.push(p);save();ui.planId=p.id;ui.dayId=p.days[0].id;go('planEditor')}
function duplicatePlan(pid){const src=S.plans.find(p=>p.id===pid);if(!src)return;let p=deep(src);p.id=id('plan');p.title=src.title+' · copia';p.status='draft';p.createdAt=now();p.days.forEach(d=>{d.id=id('day');d.items.forEach(it=>it.id=id('item'))});S.plans.push(p);save();ui.planId=p.id;ui.dayId=p.days[0]?.id;go('planEditor');toast('Copia creada como borrador')}
function activatePlan(pid){const p=S.plans.find(x=>x.id===pid);if(!p||p.status==='archived')return;const unresolved=p.days.flatMap(d=>d.items).filter(i=>!i.exerciseId);const incomplete=p.days.flatMap(d=>d.items).filter(i=>!i.sets||!i.minReps||!i.maxReps);if(!p.days.length||!p.days.some(d=>d.items.length)){alert('Primero agrega al menos un día con ejercicios.');return}if(unresolved.length||incomplete.length){alert(`Antes de activar, revisa ${unresolved.length} ejercicios sin identificar y ${incomplete.length} ejercicios con series o repeticiones incompletas.`);return}
 if(S.active&&!confirm('Hay una sesión en curso. Seguirá asociada al plan anterior aunque cambies el plan activo. ¿Continuar?'))return;
 S.plans.forEach(q=>{if(q.status==='active')q.status='archived'});p.status='active';S.activePlanId=p.id;save();go('home');toast('Plan activo actualizado')}
function archivePlan(pid){const p=S.plans.find(x=>x.id===pid);if(!p)return;if(!confirm(`¿Archivar «${p.title}»? Los entrenamientos anteriores permanecerán guardados.`))return;p.status='archived';if(S.activePlanId===p.id)S.activePlanId=null;save();go('plans')}
function savePlanInfo(){let p=currentPlan();if(!p||p.status==='archived')return;let title=$('planTitle').value.trim();if(!title){alert('El plan necesita un nombre.');return}let from=$('planStart').value,to=$('planEnd').value;if(from&&to&&to<from){alert('La fecha de término no puede ser anterior a la de inicio.');return}p.title=title.slice(0,90);p.startDate=from;p.endDate=to;p.notes=$('planNotes').value.slice(0,1000);save();render();toast('Información guardada')}
function saveDay(){let d=currentDay(),p=currentPlan();if(!d||p?.status==='archived')return;let title=$('dayTitle').value.trim();if(!title){alert('Escribe el nombre del día.');return}d.title=title.slice(0,90);d.short=$('dayShort').value.trim().slice(0,120);save();render();toast('Día actualizado')}
function deleteDay(){const p=currentPlan(),d=currentDay();if(!p||!d||p.status==='archived')return;if(!confirm('¿Quitar este día del plan? No se eliminarán sesiones que hayas registrado.'))return;p.days=p.days.filter(x=>x.id!==d.id);ui.dayId=p.days[0]?.id||null;save();render()}
function removeAssignment(itemid){const d=currentDay();if(!d||!confirm('¿Quitar el ejercicio del plan? Los registros anteriores quedarán intactos.'))return;d.items=d.items.filter(x=>x.id!==itemid);save();render()}
function changeItemOrder(itemid,diff){const d=currentDay();if(!d)return;const i=d.items.findIndex(x=>x.id===itemid),j=i+diff;if(i<0||j<0||j>=d.items.length)return;[d.items[i],d.items[j]]=[d.items[j],d.items[i]];save();render()}
function saveAssignment(){const it=currentItem();if(!it)return;const sets=Number($('aSets').value),min=Number($('aMin').value),max=Number($('aMax').value),rest=Number($('aRest').value);if(![sets,min,max,rest].every(Number.isInteger)||sets<1||sets>20||min<1||max<min||max>1000||rest<0||rest>900){alert('Revisa series, repeticiones y descanso. Repeticiones mínimas no pueden superar las máximas.');return}Object.assign(it,{sets,minReps:min,maxReps:max,restSec:rest,note:$('aNote').value.slice(0,500)});save();go('planEditor');toast('Ejercicio actualizado')}
function preparePick(replaceItemId=null){ui.pick={planId:ui.planId,dayId:currentDay()?.id,replaceItemId};ui.catQuery='';ui.catMuscle='';ui.catEquipment='';ui.catalogView=null;go('catalog')}
function chooseExercise(exid){const p=S.plans.find(x=>x.id===ui.pick?.planId),d=p?.days.find(x=>x.id===ui.pick?.dayId),ex=byExercise(exid);if(!d||!ex)return;let it=d.items.find(x=>x.id===ui.pick.replaceItemId);if(it){it.exerciseId=ex.id;it.freeName=null}else d.items.push(makeAssignment(ex.name,3,10,12,60,''));ui.planId=p.id;ui.dayId=d.id;ui.pick=null;ui.catalogView=null;save();go('planEditor');toast('Ejercicio agregado al plan')}
function newDay(){const p=currentPlan();if(!p||p.status==='archived')return;const d={id:id('day'),title:`Día ${p.days.length+1}`,short:'',items:[]};p.days.push(d);ui.dayId=d.id;save();render()}
function parseTextAndCreate(){const title=$('importTitle').value.trim().slice(0,90)||'Nuevo programa',value=$('pdfText').value;ui.importTitle=title;ui.pdfText=value;try{const result=parsePlanText(value,title);const p={id:id('plan'),title,status:'draft',startDate:'',endDate:'',notes:`Borrador desde texto: ${result.found} ejercicios detectados. Revisa las coincidencias y todos los descansos (se usa 90 s como valor inicial cuando no se especifica).`,days:result.days,createdAt:now()};S.plans.push(p);save();ui.planId=p.id;ui.dayId=p.days[0]?.id;go('planEditor');alert(`Borrador creado con ${result.found} ejercicios y ${result.skipped} líneas omitidas. Revisa los datos antes de activar.`)}catch(e){alert(e.message)}}
function saveProfile(){let age=$('pAge').value,weight=$('pWeight').value,height=$('pHeight').value;if((age&&(age<13||age>110))||(weight&&(weight<20||weight>400))||(height&&(height<100||height>250))){alert('Verifica los datos del perfil.');return}S.profile={name:$('pName').value.trim().slice(0,40),age:age?Number(age):null,weight:weight?Number(weight):null,height:height?Number(height):null,goal:$('pGoal').value};S.profileCompleted=true;save();go('home')}
function start(dayId){if(S.active){go('train');initDraft();render();toast('Continúa primero tu sesión abierta');return}let p=mainPlan(),d=p?.days.find(x=>x.id===dayId);if(!p||!d)return;if(!d.items.length){alert('Agrega ejercicios a este día antes de entrenar.');return}const snapshot=deep(d);snapshot.items.forEach(x=>x.recordedName=itemName(x));S.active={id:id('sess'),planId:p.id,planName:p.title,dayId:d.id,daySnapshot:snapshot,index:0,date:dateKey(),startedAt:now(),entries:{},warmup:{type:'none',minutes:0},cardio:{type:'none',minutes:0}};save();ui.screen='warm';render()}
function saveWarm(skip=false){const s=S.active;if(!s)return;let type=skip?'none':$('warmType').value,minutes=skip?0:Number($('warmMinutes').value||0);if(!Number.isInteger(minutes)||minutes<0||minutes>300||type!=='none'&&minutes===0){alert('Introduce una duración válida entre 1 y 300 minutos o selecciona «No registrar».');return}s.warmup={type,minutes:type==='none'?0:minutes};save();initDraft();go('train')}
function navigateExercise(index){if(!S.active)return;S.active.index=Math.max(0,Math.min(index,S.active.daySnapshot.items.length-1));initDraft();save();render()}
function logSet(){const ex=sessionExercise(),s=S.active;if(!ex||!s)return;const reps=Number($('reps').value),weight=Number($('weight').value);if(!Number.isInteger(reps)||reps<1||reps>1000||!Number.isFinite(weight)||weight<0||weight>2000){alert('Comprueba las repeticiones y la carga.');return}weightDraft={reps,weight:round(weight),unit:weightDraft.unit};(s.entries[ex.id]??=[]).push({...weightDraft,kg:round(kg(weight,weightDraft.unit),3),at:now()});S.last[ex.exerciseId||ex.freeName]=deep(weightDraft);S.unit=weightDraft.unit;let moved=false;if(s.entries[ex.id].length===ex.sets&&s.index<s.daySnapshot.items.length-1){s.index++;initDraft();moved=true}save();render();toast(moved?'Serie guardada · siguiente ejercicio':'Serie guardada')}
function undoSet(){const ex=sessionExercise(),arr=S.active?.entries[ex?.id]||[];if(!arr.length)return;const r=arr.pop();weightDraft={reps:r.reps,weight:r.weight,unit:r.unit};save();render();toast('Última serie eliminada')}
function finishSession(){const s=S.active;if(!s)return;const t=$('cardioType').value,mins=Number($('cardioMinutes').value||0);if(!Number.isInteger(mins)||mins<0||mins>300||t!=='none'&&mins===0){alert('Registra la duración del cardio o elige «Hoy no hice cardio».');return}if(!setCount(s)&&!s.warmup.minutes&&t==='none'&&!confirm('La sesión no tiene ninguna actividad. ¿Guardarla vacía?'))return;s.cardio={type:t,minutes:t==='none'?0:mins};s.finishedAt=now();S.history.unshift(deep(s));S.active=null;ui.summary=S.history[0];save();go('summary');if(S.settings.autoBackup)backup(true)}
function discardSession(){if(!confirm('¿Descartar esta sesión? Se eliminarán sus series en curso (no las sesiones anteriores).'))return;S.active=null;save();go('home')}
// Las acciones de botones se delegan: se mantienen operativas después de volver a dibujar pantallas.
document.addEventListener('click',event=>{const b=event.target.closest('button[data-act]');if(!b||b.disabled)return;const a=b.dataset.act,entityId=b.dataset.id;switch(a){
 case 'nav':ui.pick=null;ui.catalogView=null;go(b.dataset.screen);break;
 case 'settings':go('settings');break;
 case 'profile':go('profile');break;
 case 'skipProfile':S.profileCompleted=true;save();go('home');break;
 case 'newPlan':createPlan();break;
 case 'openPDF':go('pdf');break;
 case 'editActive':{let p=mainPlan();if(p){ui.planId=p.id;ui.dayId=p.days[0]?.id;go('planEditor')}break}
 case 'editPlan':{let p=S.plans.find(p=>p.id===entityId);if(p){ui.planId=p.id;ui.dayId=p.days[0]?.id;go('planEditor')}break}
 case 'duplicatePlan':duplicatePlan(entityId);break;
 case 'activatePlan':activatePlan(entityId);break;
 case 'archivePlan':archivePlan(entityId);break;
 case 'deletePlan':{let p=S.plans.find(p=>p.id===entityId);if(p?.status==='draft'&&confirm(`¿Eliminar el borrador «${p.title}»?`)){S.plans=S.plans.filter(x=>x.id!==p.id);save();go('plans')}break}
 case 'savePlanInfo':savePlanInfo();break;
 case 'newDay':newDay();break;
 case 'selectDay':ui.dayId=entityId;render();break;
 case 'saveDay':saveDay();break;
 case 'removeDay':deleteDay();break;
 case 'moveExercise':changeItemOrder(entityId,Number(b.dataset.dir));break;
 case 'removeAssignment':removeAssignment(entityId);break;
 case 'pickExercise':preparePick();break;
 case 'replaceAssignment':preparePick(entityId);break;
 case 'editAssignment':ui.itemId=entityId;go('assignmentEditor');break;
 case 'backPlan':go('planEditor');break;
 case 'saveAssignment':saveAssignment();break;
 case 'exportPlan':{let p=S.plans.find(x=>x.id===entityId);if(p){download(JSON.stringify(planExport(p),null,2),`plan-${normalize(p.title).replaceAll(' ','-')||'gym'}.json`,'application/json');toast('Plan exportado')}break}
 case 'cancelPick':ui.pick=null;ui.catalogView=null;go('planEditor');break;
 case 'detailExercise':ui.catalogView=entityId;render();break;
 case 'catalogBack':if(ui.catalogView){ui.catalogView=null;render()}else if(ui.pick){ui.pick=null;go('planEditor')}else go('catalog');break;
 case 'chooseExercise':chooseExercise(entityId);break;
 case 'clearSearch':ui.catQuery='';ui.catMuscle='';ui.catEquipment='';render();break;
 case 'newCustomExercise':go('customExercise');break;
 case 'photo':ui.photoTarget=entityId;$('imageFile').click();break;
 case 'removePhoto':if(confirm('¿Quitar la fotografía de referencia?')){delete S.photos[entityId];save();render()}break;
 case 'videoSearch':{const ex=byExercise(entityId);if(ex)window.open('https://www.youtube.com/results?search_query='+encodeURIComponent('técnica ejercicio '+ex.name),'_blank','noopener,noreferrer');break}
 case 'loadPDF':$('pdfFile').click();break;
 case 'viewPDF':if(ui.pdfURL)window.open(ui.pdfURL,'_blank','noopener');break;
 case 'parseText':parseTextAndCreate();break;
 case 'importPlan':$('planFile').click();break;
 case 'templatePlan':download(JSON.stringify(samplePlanJSON(),null,2),'plantilla-plan-bitacora-gym.json','application/json');toast('Plantilla solicitada');break;
 case 'start':start(b.dataset.day);break;
 case 'resume':initDraft();go('train');break;
 case 'saveWarm':saveWarm();break;
 case 'skipWarm':saveWarm(true);break;
 case 'backWarm':go('warm');break;
 case 'prevExercise':navigateExercise((S.active?.index||0)-1);break;
 case 'nextExercise':navigateExercise((S.active?.index||0)+1);break;
 case 'jumpExercise':navigateExercise(Number(b.dataset.index));break;
 case 'showExerciseList':{const el=$('allExercises');el.open=true;el.scrollIntoView({block:'center',behavior:'smooth'});break}
 case 'repsPlus':weightDraft.reps=Math.min(1000,(Number($('reps').value)||0)+1);$('reps').value=weightDraft.reps;break;
 case 'repsMinus':weightDraft.reps=Math.max(1,(Number($('reps').value)||1)-1);$('reps').value=weightDraft.reps;break;
 case 'weightPlus':weightDraft.weight=round(Math.max(0,Number($('weight').value)||0)+(weightDraft.unit==='kg'?2.5:5));$('weight').value=weightDraft.weight;updateConv();break;
 case 'weightMinus':weightDraft.weight=round(Math.max(0,(Number($('weight').value)||0)-(weightDraft.unit==='kg'?2.5:5)));$('weight').value=weightDraft.weight;updateConv();break;
 case 'changeUnit':{let u=b.dataset.unit;if(u!==weightDraft.unit){let n=Number($('weight')?.value)||0;weightDraft.weight=round(unitFromKg(kg(n,weightDraft.unit),u));weightDraft.unit=u;weightDraft.reps=Number($('reps')?.value)||1;render()}break}
 case 'logSet':logSet();break;
 case 'undoSet':undoSet();break;
 case 'openCardio':go('cardio');break;
 case 'backTrain':initDraft();go('train');break;
 case 'finishSession':finishSession();break;
 case 'discardSession':discardSession();break;
 case 'backup':backup();break;
 case 'restore':$('backupFile').click();break;
 case 'csv':csvExport();break;
 case 'saveSettings':S.settings.autoBackup=$('autoBackup').checked;S.settings.reminders=$('reminders').checked;S.settings.hydration=$('hydration').value.trim().slice(0,400)||defaultSettings().hydration;save();render();toast('Preferencias guardadas');break;
 default:console.warn('Acción no implementada',a);
 }});
function updateConv(){const el=$('conversion');if(el)el.textContent=conversionText()}
document.addEventListener('input',e=>{if(e.target.id==='weight'){weightDraft.weight=Number(e.target.value)||0;updateConv()};if(e.target.id==='reps'){weightDraft.reps=Number(e.target.value)||0};if(e.target.id==='catSearch'){ui.catQuery=e.target.value;if($('catResults'))$('catResults').innerHTML=catalogResults()};if(e.target.id==='pdfText')ui.pdfText=e.target.value;if(e.target.id==='importTitle')ui.importTitle=e.target.value});
document.addEventListener('change',e=>{if(e.target.id==='catMuscle'){ui.catMuscle=e.target.value;if($('catResults'))$('catResults').innerHTML=catalogResults()}if(e.target.id==='catEquipment'){ui.catEquipment=e.target.value;if($('catResults'))$('catResults').innerHTML=catalogResults()}});
document.addEventListener('submit',e=>{if(e.target.id==='profileForm'){e.preventDefault();saveProfile()}
 if(e.target.id==='customForm'){e.preventDefault();const name=$('exName').value.trim(),muscle=$('exMuscle').value,equipment=$('exEquipment').value;if(!name)return;const existing=findExercise(name);if(existing){alert(`Ya existe un ejercicio con este nombre: ${existing.name}`);return}
 const x={id:id('custom'),name:name.slice(0,100),aliases:$('exAliases').value.split(',').map(a=>a.trim()).filter(Boolean).slice(0,10),muscle,equipment,family:'core',instructions:$('exInstructions').value.split(/\r?\n/).map(a=>a.trim()).filter(Boolean).slice(0,12),custom:true};S.customCatalog.push(x);save();if(ui.pick){chooseExercise(x.id)}else{ui.catalogView=x.id;go('catalog')}toast('Ejercicio personalizado guardado')}});
let swipeStart=null;
document.addEventListener('touchstart',e=>{let zone=e.target.closest('#swipeZone');if(!zone||e.touches.length!==1||e.target.closest('button,input,a,textarea,select'))return;swipeStart={x:e.touches[0].clientX,y:e.touches[0].clientY}},{passive:true});
document.addEventListener('touchend',e=>{if(!swipeStart||ui.screen!=='train')return;const deltaX=e.changedTouches[0].clientX-swipeStart.x,deltaY=e.changedTouches[0].clientY-swipeStart.y;swipeStart=null;if(Math.abs(deltaX)>65&&Math.abs(deltaX)>Math.abs(deltaY)*1.5)navigateExercise(S.active.index+(deltaX<0?1:-1))},{passive:true});
async function compressedPhoto(file){const source=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('No se pudo leer la foto'));r.readAsDataURL(file)});const img=await new Promise((resolve,reject)=>{let i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('La imagen no es válida'));i.src=source});const ratio=Math.min(1,750/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*ratio));canvas.height=Math.max(1,Math.round(img.height*ratio));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.65)}
$('imageFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(!file.type.startsWith('image/'))throw Error('Selecciona una imagen');if(file.size>16*1024*1024)throw Error('La imagen es demasiado grande');if(!ui.photoTarget)throw Error('Ejercicio no seleccionado');S.photos[ui.photoTarget]=await compressedPhoto(file);await save();render();toast('Foto guardada en la app y en el próximo respaldo')}catch(err){alert(err.message)}finally{e.target.value=''}});
$('pdfFile').addEventListener('change',e=>{const file=e.target.files?.[0];if(!file)return;if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf')){alert('Selecciona un PDF válido');return}if(file.size>40*1024*1024){alert('Para la vista previa, utiliza un PDF de hasta 40 MB.');return}if(ui.pdfURL)URL.revokeObjectURL(ui.pdfURL);ui.pdfURL=URL.createObjectURL(file);ui.pdfName=file.name;render();e.target.value=''});
$('planFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('El archivo del plan supera 2 MB');const content=JSON.parse(await file.text()),plan=normalizePlanImport(content);S.plans.push(plan);save();ui.planId=plan.id;ui.dayId=plan.days[0]?.id||null;go('planEditor');toast('Plan importado como borrador: revisa los ejercicios')}catch(err){alert('No se pudo importar el plan: '+err.message)}finally{e.target.value=''}});
function migrateBackupV2(raw){const old=raw?.data||raw;if(!old||old.version!==2||!Array.isArray(old.history))return null;let fresh=initial(),saveS=S;S=fresh;seedPlan();const plan=S.plans[0];try{
 const convert=(x)=>{const d=plan.days[Number(x.day)||0],snap=deep(d||plan.days[0]);snap.items.forEach(it=>it.recordedName=itemName(it));let entries={};for(const [i,it] of snap.items.entries()){const oldkey=`${x.day}-${i}`;if(Array.isArray(x.entries?.[oldkey]))entries[it.id]=deep(x.entries[oldkey])}return {id:id('sess'),planId:plan.id,planName:plan.title,dayId:snap.id,daySnapshot:snap,index:Number(x.index)||0,date:x.dateKey||x.date||dateKey(),startedAt:x.startedAt||now(),finishedAt:x.finishedAt||now(),entries,warmup:x.warmup||{type:'none',minutes:0},cardio:x.cardio||{type:'none',minutes:0}}};
 fresh.history=old.history.map(convert);fresh.active=old.active?convert(old.active):null;fresh.profile=old.profile||fresh.profile;fresh.profileCompleted=!!old.profileCompleted;fresh.settings={...fresh.settings,...old.settings};fresh.photos={};fresh.last={};for(let di=0;di<3;di++)for(let ix=0;ix<plan.days[di].items.length;ix++){const oldid=di+'-'+ix,catid=plan.days[di].items[ix].exerciseId;if(!catid)continue;if(old.photos?.[oldid])fresh.photos[catid]=old.photos[oldid];if(old.last?.[oldid])fresh.last[catid]=old.last[oldid]}fresh.unit=old.unit||'kg';return fresh;
 }finally{S=saveS}}
$('backupFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>25*1024*1024)throw Error('Archivo demasiado grande');const raw=JSON.parse(await file.text()),data=raw.data||raw;const incoming=data?.version===3?validateStore(data):migrateBackupV2(raw);if(!incoming)throw Error('Versión de respaldo no reconocida');if(!confirm(`¿Restaurar el respaldo? Contiene ${incoming.history.length} sesiones y ${incoming.plans.length} planes. REEMPLAZARÁ los datos actuales del navegador. Descarga primero una copia si la necesitas.`))return;S=incoming;await save();ui.pick=null;ui.planId=null;ui.dayId=null;ui.summary=null;go('home');toast('Respaldo restaurado')}catch(err){alert('No se pudo restaurar: '+err.message)}finally{e.target.value=''}});
// Inicio
load().catch(e=>{console.error(e);storageState='limited';if(!S.plans.length)seedPlan();go('home')});
